 import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    DataTexture,
    DirectionalLight,
    Vector3,
    Color
  } = THREE;

  const group = new Group();
  group.userData.handlers = {};

  const colors = config.intent?.visualSpec?.colors || config.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find(i => i.role === 'headline') || items[0];
  const fontSize = headline?.typography?.fontSize ?? 39;

  // Stage: engineered vertical gradient backdrop
  const backdropGeo = new PlaneGeometry(7, 6);
  const gradient = mix(
    color(colors.ink),
    color(colors.surface),
    smoothstep(0.0, 1.0, uv().y)
  );
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = gradient;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Card content group (animated independently from adapter-applied scene transform)
  const content = new Group();

  // Machined-metal label plane
  const labelWidth = 1.4;
  const labelHeight = labelWidth * (320 / 512);
  const labelGeo = new PlaneGeometry(labelWidth, labelHeight);
  const labelMat = new MeshStandardNodeMaterial({
    color: new Color('#2a2a30'),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.12,
    clearcoatRoughness: 0.45,
    side: THREE.FrontSide,
    transparent: true,
    opacity: 0
  });
  const label = new Mesh(labelGeo, labelMat);
  content.add(label);

  // Text
  if (headline?.text) {
    const textMesh = ctx.fontAtlas.createText(headline.text, {
      fontSize,
      color: colors.paper,
      align: 'left'
    });
    textMesh.position.set(-labelWidth / 2 + 0.12, 0, 0.02);
    textMesh.scale.setScalar(0.006);
    content.add(textMesh);
  }

  // Subtle radial contact-shadow behind the card
  const shadowSize = 128;
  const shadowData = new Uint8Array(shadowSize * shadowSize * 4);
  for (let y = 0; y < shadowSize; y++) {
    for (let x = 0; x < shadowSize; x++) {
      const u = x / (shadowSize - 1) - 0.5;
      const v = y / (shadowSize - 1) - 0.5;
      const d = Math.sqrt(u * u + v * v) * 2.2;
      const a = Math.max(0, 1 - d) * 0.5 * 255;
      const idx = (y * shadowSize + x) * 4;
      shadowData[idx] = 0;
      shadowData[idx + 1] = 0;
      shadowData[idx + 2] = 0;
      shadowData[idx + 3] = a;
    }
  }
  const shadowTex = new DataTexture(shadowData, shadowSize, shadowSize);
  shadowTex.needsUpdate = true;
  const shadowGeo = new PlaneGeometry(labelWidth * 1.15, labelHeight * 1.15);
  const shadowMat = new MeshBasicNodeMaterial({
    map: shadowTex,
    transparent: true,
    opacity: 0.45,
    depthWrite: false
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.z = -0.06;
  content.add(shadow);

  group.add(content);

  // Node-local rim/accent light for metal readability
  const rim = new DirectionalLight(colors.paper, 0.8);
  rim.position.set(-2, 1.5, -3);
  group.add(rim);

  // Entrance motion
  content.scale.set(0.98, 0.98, 0.98);
  content.position.y = -0.04;

  const enterTl = gsap.timeline({ delay: 0.05 });
  enterTl.to(
    content.position,
    { y: 0, duration: 0.7, ease: 'power3.out' },
    0
  );
  enterTl.to(
    content.scale,
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0
  );

  // Async texture load
  const texPromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.wrapS = THREE.ClampToEdgeWrapping;
      tex.wrapT = THREE.ClampToEdgeWrapping;
      labelMat.map = tex;
      labelMat.needsUpdate = true;
      gsap.to(labelMat, { opacity: 1, duration: 0.5, ease: 'power2.out' });
    })
    .catch(() => {
      gsap.to(labelMat, { opacity: 1, duration: 0.5, ease: 'power2.out' });
    });

  const disposeObject = (obj) => {
    obj.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        mats.forEach((m) => {
          if (m.map) m.map.dispose();
          if (m.alphaMap) m.alphaMap.dispose();
          m.dispose();
        });
      }
    });
  };

  group.userData.cleanup = () => {
    enterTl.kill();
    disposeObject(group);
    if (shadowTex) shadowTex.dispose();
  };

  return group;
}
